@startuml

class City {
  + Name : string
}

class H2SLocation {
  + LocationID : int
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class ScheduledPickup {
  + Description : string
  + RequestedDay : date
  + PickupTime : time
}

class Vehicle {
  + Capacity : float
  + Dimensions : string
  + WeightLimit : float
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class PickupRoute {
  + RouteID : int
}

class DistributionCenter {
  + LocationID : int
}

class FoodBank {
  + LocationID : int
}

class Article {
  + RFIDTag : string
  + Description : string
  + Category : string
}

class H2SEmployee {
  + EmployeeID : int
  + Name : string
}

class Client {
  + Name : string
  + HomeAddress : string
}

class Category {
  + CategoryName : string
}

H2SLocation "*" -- "1" City
H2SLocation "1" *-- "1" DistributionCenter
H2SLocation "1" *-- "0..1" FoodBank

Resident "1" -- "*" ScheduledPickup
ScheduledPickup "*" -- "1" Resident

Vehicle "1" -- "*" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute
PickupRoute "1" -- "*" ScheduledPickup

ScheduledPickup "*" -- "1" Vehicle

DistributionCenter "1" -- "*" Article
H2SEmployee "1" -- "*" Article
Article "*" -- "1" Category

Client "1" -- "*" Category : requests
H2SEmployee "1" -- "*" Client : calls
H2SEmployee "1" -- "*" Article : delivers

@enduml

